#!/usr/bin/env node
// Token names (decided Nov 23, 2026: N1–N8; roles from B1, B2, C1, C2, C4, M1, M2, H1). Old names stay as aliases until 3.0.
//   node tools/gen-token-names.mjs                    → writes src/foundations/deprecated.css (every old name = var(--new name))
//   node tools/gen-token-names.mjs --codemod <path>…  → rewrites old token names to the new ones in those files / folders
//   node tools/gen-token-names.mjs --check            → lists old names still used in src/components, src/gallery, demo/screens
// Source: tools/figma/rename-map.tsv, generated by prototypes/phase1-prep/naming-colour/data/gen-rename-map.mjs
// (columns: family, old Figma, old CSS, new Figma, new CSS, kind, Dark value, uses, note).
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const rows = readFileSync(join(root, 'tools/figma/rename-map.tsv'), 'utf8').trim().split('\n').slice(1).map(l => l.split('\t'));
const isName = s => /^--[a-z0-9-]+$/.test(s || '');
// Old → new. Skipped: the held colours (unchanged), Figma-only rows, and the margins / gutters folders
// (their aliases keep their own fixed values, so they are not the same as --page-margin / --page-gap).
export const MAP = new Map();
for (const r of rows) {
  const [, , oldCss, , newCss, kind] = r;
  if (!isName(oldCss) || !isName(newCss) || oldCss === newCss) continue;
  if (/^held|^keep/.test(kind) || /^--(margins|gutters)-/.test(oldCss)) continue;
  MAP.set(oldCss, newCss);
}
// The pre-2.0.6 data-viz names (tools/figma/legacy-dataviz-aliases.css): old name → the current role (F-4 / F-3). Used by --check, and to
// point every alias straight at a current name (no alias → alias chains).
const LEGACY_DV = new Map([...readFileSync(join(root, 'tools/figma/legacy-dataviz-aliases.css'), 'utf8')
  .matchAll(/(--[a-z0-9-]+)\s*:\s*var\((--[a-z0-9-]+)\)/g)].map(m => [m[1], m[2]]));
export const finalName = n => { const seen = new Set(); while ((MAP.has(n) || LEGACY_DV.has(n)) && !seen.has(n)) { seen.add(n); n = MAP.get(n) || LEGACY_DV.get(n); } return n; };
const re = new RegExp(`(${[...MAP.keys()].sort((a, b) => b.length - a.length).map(s => s.replace(/[-]/g, '\\-')).join('|')})(?![\\w-])`, 'g');
export const rename = s => s.replace(re, m => MAP.get(m));

const walk = p => statSync(p).isDirectory() ? readdirSync(p).flatMap(f => walk(join(p, f))) : [p];
const args = process.argv.slice(2);
const main = import.meta.url === pathToFileURL(process.argv[1] || '').href;
if (!main) { /* imported as a module */ } else if (args[0] === '--codemod') {
  // --only <prefix>: rename only the names whose new name starts with --<prefix> (e.g. --only color)
  const oi = args.indexOf('--only'), only = oi > 0 ? '--' + args.splice(oi, 2)[1] : '';
  const sub = new Map([...MAP].filter(([, n]) => n.startsWith(only)));
  const re2 = new RegExp(`(${[...sub.keys()].sort((a, b) => b.length - a.length).map(s => s.replace(/[-]/g, '\\-')).join('|')})(?![\\w-])`, 'g');
  let n = 0;
  for (const f of args.slice(1).flatMap(walk).filter(f => /\.(css|jsx?|mjs|html|md|mdx)$/.test(f))) {
    const a = readFileSync(f, 'utf8'), b = a.replace(re2, m => sub.get(m));
    if (a !== b) { writeFileSync(f, b); n++; }
  }
  console.log(`codemod: ${n} files changed`);
} else if (args[0] === '--check') {
  const hits = {};
  const reAll = new RegExp(`(${[...MAP.keys(), ...LEGACY_DV.keys()].sort((a, b) => b.length - a.length).map(s => s.replace(/[-]/g, '\\-')).join('|')})(?![\\w-])`, 'g');
  for (const f of ['src/components', 'src/gallery', 'demo/screens'].flatMap(d => walk(join(root, d))).filter(f => /\.(css|jsx?)$/.test(f)))
    for (const m of readFileSync(f, 'utf8').matchAll(reAll)) hits[m[1]] = (hits[m[1]] || 0) + 1;
  // Audit T-8 (Nov 26): names built at run time ('sequential-orchid-4' in a lookup table, `sequential-${fam}-…`) have no "--color-" prefix,
  // so the full-name scan above misses them. Flag the deprecated ramp family names wherever they appear after "sequential-".
  const reFam = /sequential-(orchid|pink|yellow|cyan)-\d/g;
  for (const f of ['src/components', 'src/gallery', 'demo/screens'].flatMap(d => walk(join(root, d))).filter(f => /\.(css|jsx?)$/.test(f)))
    for (const m of readFileSync(f, 'utf8').matchAll(reFam)) { const k = `sequential-${m[1]}-* (${f.split('/').slice(-2).join('/')})`; hits[k] = (hits[k] || 0) + 1; }
  console.log(Object.keys(hits).length ? hits : 'no old token names in components, gallery or demo screens');
} else {
  // Aliases are declared on every density container too, so an old density-dependent name (--type-m, --control-h-m,
  // --text-body-m-regular) resolves at the nearest data-density, exactly like the new one.
  const legacy = readFileSync(join(root, 'tools/figma/legacy-spacing-aliases.css'), 'utf8').trim();
  // 2.0.6: the pre-2.0.6 data-viz ramps and data-1…10, each pointing at the nearest new data-viz role (D6 / D7 / D8)
  const legacyDataViz = readFileSync(join(root, 'tools/figma/legacy-dataviz-aliases.css'), 'utf8').trim();
  const lines = [...MAP].filter(([o]) => !/^--(gaps|paddings|spacing)-/.test(o)).map(([o, n]) => `${o}:var(${finalName(n)});`);
  writeFileSync(join(root, 'src/foundations/deprecated.css'), `/* Deprecated token names (generated by tools/gen-token-names.mjs; do not edit). Every old name points at its new name
   and keeps working until 3.0. New code uses the new names (dist/tokens.txt); dist/tokens.json marks these $deprecated.
   Not here: the 5 colours held (they keep their old names and values until they are decided). */
:root,[data-density]{
${lines.join('\n')}
}
/* Older aliases (gaps, paddings, margins, gutters, spacing folders), kept with their own values */
${legacy}
${legacyDataViz}
`);
  console.log(`deprecated.css: ${lines.length} aliases + the legacy spacing folders`);
}
